//! 📖️ Actual continuous-tool ledgers lend one native state under its original Job and decoder.
use super::*;
use semio_framework_value::{retirement::RetireOwned,SharedUtf8};
use semio_framework_value::retained_clone::{original_slot::RetainedOriginalSlotKey,RetainedCloneClose,RetainedCloneRef};
use semio_framework_tool_machine::OriginalToolLedgerSource;
use semio_framework_job::OriginalSourceBinding;
type Issuer<S>=Arc<dyn semio_framework_value::ArtifactOwnedValueRetirementFactory<S>>;
/// 🔗️ A source owner keeps its actual resident key, immutable issuer and original caller until return.
pub struct OriginalToolLedgerRead<S:RetireOwned+Send+Sync+'static>{binding:Option<OriginalSourceBinding>,decoder:Option<(u64,u64)>,revision:u64,window:Option<SharedUtf8>,key:Option<RetainedOriginalSlotKey>,factory:Option<Issuer<S>>,returned_factory:Option<Issuer<S>>,factory_close:Option<FactoryAuthority>,retirement:RetainedCloneClose,ready:bool,returned:bool,closing:bool}
impl<S:RetireOwned+Send+Sync+'static> Default for OriginalToolLedgerRead<S>{fn default()->Self{Self{binding:None,decoder:None,revision:0,window:None,key:None,factory:None,returned_factory:None,factory_close:None,retirement:Default::default(),ready:false,returned:false,closing:false}}}
impl<S:RetireOwned+Send+Sync+'static> OriginalToolLedgerRead<S>{
 fn validate(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if !self.binding.is_some_and(|binding|binding.matches(cx))||cx.native_receiving_identity()!=self.decoder{return Err(invalid("original tool state read changed its caller or decoder"))}Ok(())}
 /// 📏️ Quotes the authentic resident alias and source fence before any admission.
 pub fn admission_demands()->RetirementDemand{header::<(OriginalSourceBinding,(u64,u64),u64,SharedUtf8,RetainedOriginalSlotKey)>()}
 /// 📥️ Captures the same declared resident instead of materializing its variable state or leaves.
 pub fn admit<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&L,window:&SharedUtf8,key:RetainedOriginalSlotKey,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.binding.is_some()||self.closing||!ledger.original_live(window,key)?{return Err(invalid("original tool state read requires its live resident and empty recipient").into())}let binding=OriginalSourceBinding::borrow(cx);let d=Self::admission_demands();let mut done=None;semio_framework_job::admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(||invalid("original tool state read requires its actual decoder recipient"))?);self.binding=Some(binding);self.decoder=Some(decoder);self.revision=ledger.original_revision();self.window=Some(window.clone());self.key=Some(key);Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(done.is_some())}
 fn issuer_demand()->RetirementDemand{type Factory<S>=semio_framework_value::factory::OwnedValueRetirementFactory<S>;RetirementDemand{copy_bytes:size_of::<Factory<S>>()+2*size_of::<Issuer<S>>(),capacity_bytes:semio_framework_value::shared_retirement_allocation_bytes::<Factory<S>>(),depth:1,..Default::default()}}
 /// 📏️ Quotes the next original issuer or immutable state-source birth.
 pub fn demands<L:OriginalToolLedgerSource<State=S>>(&self,ledger:&L,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands(ledger,body)}if self.binding.is_none(){return Ok(Self::admission_demands())}if self.ready{return Ok(Default::default())}if self.factory.is_none(){return Ok(Self::issuer_demand())}let mut d=ledger.original_read_demands(self.window.as_ref().unwrap(),self.key.unwrap())?;d.copy_bytes+=size_of::<bool>();Ok(d)}
 /// 🪜️ The actual ledger retains its original state and captured issuer while the reader is issued.
 pub fn advance<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&mut L,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing||ledger.original_revision()!=self.revision{return Err(invalid("original tool state read requires its unchanged source frontier").into())}if self.ready{return Ok(true)}let d=self.demands(ledger,4096)?;if self.factory.is_none(){paid(cx,d,|_|{self.factory=Some(Arc::new(semio_framework_value::factory::OwnedValueRetirementFactory::<S>::default()));Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})})?;return Ok(false)}paid(cx,d,|g|{let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<bool>(),..g};let step=ledger.original_read_advance(self.window.as_ref().unwrap(),self.key.unwrap(),self.factory.as_ref().unwrap(),child)?;if matches!(step,RetainedCloneStep::Complete(_)){self.ready=true;}let mut p=step.progress();p.copied_items=p.copied_items.max(1);p.copied_bytes+=size_of::<bool>();Ok(p)})?;Ok(self.ready)}
 /// 📖️ Borrows the original immutable native state while its authentic resident source remains issued.
 pub fn borrow<'a,L:OriginalToolLedgerSource<State=S>>(&self,ledger:&'a L)->Result<RetainedCloneRef<'a,S>,ValueError>{if !self.ready||self.closing||ledger.original_revision()!=self.revision{return Err(invalid("original tool state source is incomplete or moved"))}ledger.original_read(self.window.as_ref().unwrap(),self.key.unwrap())}
 /// ✅️ Readiness never donates or copies the original row.
 pub fn ready(&self)->bool{self.ready&&!self.closing}
 /// 📏️ Closure keeps the same resident and factory even when another window moves the global source frontier.
 pub fn close_demands<L:OriginalToolLedgerSource<State=S>>(&self,ledger:&L,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(if self.binding.is_none(){header::<(bool,bool)>()}else{header::<bool>()})}if !self.returned{let mut d=ledger.original_return_demands(self.window.as_ref().unwrap(),self.key.unwrap(),body)?;d.copy_bytes+=size_of::<bool>();return Ok(d)}if let Some(owner)=self.factory_close.as_ref(){return if owner.terminal_is_empty(){Ok(header::<Option<FactoryAuthority>>())}else{owner.demands(body)}}if self.returned_factory.is_some()||self.factory.is_some(){return Ok(header::<(Issuer<S>,FactoryAuthority)>())}if !self.retirement.is_empty()||self.window.is_some(){return self.retirement.next_owner_demands::<SharedUtf8>(self.window.is_some(),&None,body)}if self.binding.is_some(){return Ok(header::<(Option<OriginalSourceBinding>,Option<(u64,u64)>,Option<RetainedOriginalSlotKey>)>())}Ok(Default::default())}
 /// ♻️ Returns every actual state lease before closing its captured issuers and original window alias.
 pub fn close_step<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&mut L,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}if self.binding.is_none()&&!self.closing{let d=header::<(bool,bool)>();close_paid(cx,d,|_|{self.closing=true;self.returned=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(self.terminal_is_empty())}self.validate(cx)?;let d=self.close_demands(ledger,4096)?;if !self.closing{close_paid(cx,d,|_|{self.closing=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if !self.returned{close_paid(cx,d,|g|{let step=ledger.original_return(self.window.as_ref().unwrap(),self.key.unwrap(),&mut self.returned_factory,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<bool>(),..g})?;if matches!(step,RetainedCloneStep::Complete(_)){self.returned=true;}let mut p=step.progress();p.copied_items=p.copied_items.max(1);p.copied_bytes+=size_of::<bool>();Ok(p)})?;return Ok(false)}if let Some(owner)=self.factory_close.as_mut(){if owner.terminal_is_empty(){close_paid(cx,d,|_|{self.factory_close=None;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;}else{semio_framework_job::close_original_retained_step(cx,d,|g|owner.step(g))?;}return Ok(false)}if self.returned_factory.is_some()||self.factory.is_some(){close_paid(cx,d,|_|{let factory=self.returned_factory.take().or_else(||self.factory.take()).unwrap();self.factory_close=Some(FactoryAuthority::new(factory));Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if !self.retirement.is_empty()||self.window.is_some(){semio_framework_job::close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){self.retirement.step_granted(g)}else{Ok(self.retirement.begin_granted(&mut self.window,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}})?;return Ok(false)}if self.binding.is_some(){close_paid(cx,d,|_|{self.binding=None;self.decoder=None;self.key=None;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}Ok(true)}
 /// 🧺️ Terminal custody includes the issued state, both original issuer aliases and the resident address.
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.returned&&self.binding.is_none()&&self.key.is_none()&&self.window.is_none()&&self.factory.is_none()&&self.returned_factory.is_none()&&self.factory_close.is_none()&&self.retirement.is_empty()}
}
impl<S:RetireOwned+Send+Sync+'static> Drop for OriginalToolLedgerRead<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty()||self.binding.is_none()&&!self.closing,"original tool state reader requires original funded closure")}}

#[path="🧭️walk/🦀️.rs"]
mod walk;
pub use walk::OriginalToolLedgerWalk;
